#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<long long> P(K + 1);
    for (int i = 1; i <= K; ++i) cin >> P[i];

    vector<vector<pair<int,int>>> edgesByColor(K + 1);
    for (int i = 0; i < M; ++i) {
        int v, u, t;
        cin >> v >> u >> t;
        edgesByColor[t].push_back(make_pair(v, u));
    }

    int A, B;
    cin >> A >> B;

    vector<int> parent(N + 1), sz(N + 1), seen(N + 1, 0);
    vector<int> markRoot(N + 1, 0), compRootId(N + 1, 0);
    vector<vector<pair<int,long long>>> adj(N + 1);

    function<int(int)> find = [&](int x) -> int {
        if (parent[x] == x) return x;
        return parent[x] = find(parent[x]);
    };

    auto unite = [&](int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    };

    for (int c = 1; c <= K; ++c) {
        if (edgesByColor[c].empty()) continue;

        for (size_t i = 0; i < edgesByColor[c].size(); ++i) {
            int u = edgesByColor[c][i].first;
            int v = edgesByColor[c][i].second;

            if (seen[u] != c) {
                seen[u] = c;
                parent[u] = u;
                sz[u] = 1;
            }
            if (seen[v] != c) {
                seen[v] = c;
                parent[v] = v;
                sz[v] = 1;
            }

            unite(u, v);
        }

        for (size_t i = 0; i < edgesByColor[c].size(); ++i) {
            int u = edgesByColor[c][i].first;
            int v = edgesByColor[c][i].second;

            int r = find(u);
            int comp;
            if (markRoot[r] != c) {
                markRoot[r] = c;
                comp = (int)adj.size();
                compRootId[r] = comp;
                adj.emplace_back();
            } else {
                comp = compRootId[r];
            }

            long long w = P[c];

            adj[u].push_back(make_pair(comp, w));
            adj[comp].push_back(make_pair(u, 0LL));

            adj[v].push_back(make_pair(comp, w));
            adj[comp].push_back(make_pair(v, 0LL));
        }
    }

    const long long INF = (1LL << 60);
    vector<long long> dist(adj.size(), INF);

    priority_queue<
        pair<long long,int>,
        vector<pair<long long,int>>,
        greater<pair<long long,int>>
    > pq;

    dist[A] = 0;
    pq.push(make_pair(0, A));

    while (!pq.empty()) {
        pair<long long,int> cur = pq.top();
        pq.pop();

        long long d = cur.first;
        int u = cur.second;

        if (d != dist[u]) continue;

        for (size_t i = 0; i < adj[u].size(); ++i) {
            int v = adj[u][i].first;
            long long w = adj[u][i].second;

            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push(make_pair(dist[v], v));
            }
        }
    }

    if (dist[B] == INF) cout << -1 << '\n';
    else cout << dist[B] << '\n';

    return 0;
}
